const dgStorageWarningState={warned:!1};function dgWarnStorageFailure(e,r,t){dgStorageWarningState.warned||(dgStorageWarningState.warned=!0,console.warn(`[Daily Genre] Browser storage is unavailable. The app will continue, but some preferences may not persist. First failure: ${e} "${String(r||"")}".`,t))}function dgResolveStorage(e="local"){return"session"===e?window.sessionStorage:window.localStorage}function safeStorageGet(e,r=null,t="local"){try{const a=dgResolveStorage(t).getItem(e);return null===a?r:a}catch(t){return dgWarnStorageFailure("read",e,t),r}}function safeStorageSet(e,r,t="local"){try{return dgResolveStorage(t).setItem(e,r),!0}catch(r){return dgWarnStorageFailure("write",e,r),!1}}function safeStorageRemove(e,r="local"){try{return dgResolveStorage(r).removeItem(e),!0}catch(r){return dgWarnStorageFailure("remove",e,r),!1}}function safeSessionStorageGet(e,r=null){return safeStorageGet(e,r,"session")}function safeSessionStorageSet(e,r){return safeStorageSet(e,r,"session")}function safeSessionStorageRemove(e){return safeStorageRemove(e,"session")}function isDailyGenreMobilePerfMode(){try{return Boolean(window.__dgForceMobilePerf||window.matchMedia&&window.matchMedia("(max-width: 760px)").matches||/iPhone|iPad|iPod|Android/i.test(navigator.userAgent||""))}catch(e){return!1}}function escapeHtml(e=""){return String(e).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#39;")}function normalizeName(e=""){return String(e).toLowerCase().replace(/&/g," and ").replace(/[^a-z0-9]+/g," ").replace(/\s+/g," ").trim()}function categoryLine(e){return e.category_path||e.categorypath||e.subcategory||"Uncategorized"}function dateValue(e){return e.date_normalized||e.datenormalized||""}function normalizedGenreStatus(e){return String(e?.status||"").trim().toLowerCase()}function isGenreZanger(e){const r=normalizedGenreStatus(e),t=String(e?.rating||"").trim().toLowerCase();return"veto"===r||"zanger"===r||"zanger"===t}